from html import escape
def page(title,description,example):
    import json
    return """<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>"""+escape(title)+"""</title>
<style>body{margin:0;background:#101820;color:#e5f0f3;font:16px system-ui}main{max-width:1050px;margin:auto;padding:48px 24px}h1{font-size:46px;letter-spacing:-2px;margin-bottom:8px}p{color:#b3c9d0;line-height:1.6}section{margin-top:26px;border:1px solid #3a535c;border-radius:12px;padding:24px;background:#15232b}textarea{box-sizing:border-box;width:100%;min-height:230px;background:#0c141a;color:#dcf5ee;border:1px solid #52717b;padding:16px;font:14px monospace}button{background:#7ce6bc;color:#08261a;border:0;border-radius:6px;padding:12px 20px;font-weight:bold;margin-top:12px;cursor:pointer}pre{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.45}a{color:#7ce6bc}.tag{font:12px monospace;text-transform:uppercase;letter-spacing:2px;color:#7ce6bc}</style>
<main><span class="tag">Engineering laboratory / reproducible demo</span><h1>"""+escape(title)+"""</h1><p>"""+escape(description)+"""</p><p><a href="/docs">API documentation</a> · Local prototype; synthetic data.</p><section><label for="input">Experiment configuration (JSON)</label><textarea id="input">"""+escape(json.dumps(example,indent=2))+"""</textarea><button id="run">Run experiment</button><p id="status" role="status"></p></section><section><h2>Results and evidence</h2><pre id="output">Run an experiment to inspect its result.</pre></section></main>
<script>document.getElementById('run').onclick=async()=>{const b=document.getElementById('run'),s=document.getElementById('status');b.disabled=true;s.textContent='Running…';try{const payload=JSON.parse(document.getElementById('input').value);const r=await fetch('/demo',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const d=await r.json();document.getElementById('output').textContent=JSON.stringify(d,null,2);s.textContent=r.ok?'Experiment complete':'Request rejected'}catch(e){s.textContent=e.message}finally{b.disabled=false}};</script></html>"""
